<?php
declare(strict_types=1); require_once __DIR__.'/lvmf_2026_lib.php'; lvmf_2026_auth();
try{$pg=lvmf_2026_pg();$sql="SELECT 'legacy' kind,m.new_view_code,m.legacy_view_ref,a.area_code,ST_AsGeoJSON(ST_Transform(a.geom,4326)) geometry FROM lvmf_legacy_comparison_areas a JOIN lvmf_legacy_comparison_matches m ON m.id=a.match_id UNION ALL SELECT 'appendix_e',v.view_code new_view_code,m.legacy_view_ref,a.area_code,ST_AsGeoJSON(ST_Transform(a.geom,4326)) FROM lvmf_2026_areas a JOIN lvmf_2026_views v ON v.id=a.view_id JOIN lvmf_2026_datasets d ON d.id=v.dataset_id LEFT JOIN lvmf_legacy_comparison_matches m ON m.dataset_id=d.id AND m.new_view_code=v.view_code WHERE d.version_label='2026-consultation-draft'";$features=[];foreach($pg->query($sql) as $r)$features[]=['type'=>'Feature','geometry'=>json_decode($r['geometry'],true),'properties'=>array_diff_key($r,['geometry'=>true])];$metrics=$pg->query("SELECT m.new_view_code,m.legacy_view_ref,r.area_code,r.jaccard,r.symmetric_difference_m2,r.hausdorff_m,r.height_profile_json FROM lvmf_legacy_comparison_results r JOIN lvmf_legacy_comparison_matches m ON m.id=r.match_id ORDER BY r.symmetric_difference_m2 DESC")->fetchAll();docling_json_out(200,['success'=>true,'areas'=>['type'=>'FeatureCollection','features'=>$features],'metrics'=>$metrics]);}catch(Throwable $e){error_log('[lvmf-comparison] '.$e->getMessage());lvmf_2026_json_error(500,'Unable to load comparison.');}
